import{_ as a,D as r,o as d,c as i,j as e,a as o,I as l,w as s,am as m}from"./chunks/framework.DXw8qDd0.js";const M=JSON.parse('{"title":"Codex的Memory机制详解","description":"","frontmatter":{"title":"Codex的Memory机制详解","time":"2026-06-07T00:00:00.000Z","tags":["codex"]},"headers":[],"relativePath":"笔记/Codex/Codex的Memory机制详解.md","filePath":"笔记/Codex/Codex的Memory机制详解.md"}'),n={name:"笔记/Codex/Codex的Memory机制详解.md"},h=m('<h1 id="codex-的-memory-机制详解" tabindex="-1">Codex 的 Memory 机制详解 <a class="header-anchor" href="#codex-的-memory-机制详解" aria-label="Permalink to &quot;Codex 的 Memory 机制详解&quot;">​</a></h1><hr><h2 id="什么是-memory" tabindex="-1">什么是 Memory <a class="header-anchor" href="#什么是-memory" aria-label="Permalink to &quot;什么是 Memory&quot;">​</a></h2><p>Codex 的 Memory（记忆）是一种跨会话的持久化记忆系统。它可以把你在对话中强调的重要信息保存下来，在以后的新对话中自动加载，让 Codex 记住你的偏好和项目规则。</p><p>简单说：Memory = 让 Codex 在新对话中也记得「你是谁」「你在意什么」「你的项目有什么规矩」。</p><hr><h2 id="memory-的存储位置" tabindex="-1">Memory 的存储位置 <a class="header-anchor" href="#memory-的存储位置" aria-label="Permalink to &quot;Memory 的存储位置&quot;">​</a></h2><p>Memory 文件存放在：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>C:\\Users\\&lt;你的用户名&gt;\\.codex\\memories\\</span></span></code></pre></div><p>这是一个目录，里面存放 Codex 自动或手动保存的记忆条目。</p><hr><h2 id="如何开启和使用-memory" tabindex="-1">如何开启和使用 Memory <a class="header-anchor" href="#如何开启和使用-memory" aria-label="Permalink to &quot;如何开启和使用 Memory&quot;">​</a></h2><h3 id="方法一-通过-memories-斜杠命令" tabindex="-1">方法一：通过 /memories 斜杠命令 <a class="header-anchor" href="#方法一-通过-memories-斜杠命令" aria-label="Permalink to &quot;方法一：通过 /memories 斜杠命令&quot;">​</a></h3><p>在 Codex CLI 或桌面 App 的对话输入框中，输入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>/memories</span></span></code></pre></div><p>这会打开 Memory 配置界面，你可以：</p><ul><li>查看当前已有的记忆条目</li><li>配置记忆的使用方式和生成方式</li><li>管理记忆内容</li></ul><h3 id="方法二-在对话中自然触发" tabindex="-1">方法二：在对话中自然触发 <a class="header-anchor" href="#方法二-在对话中自然触发" aria-label="Permalink to &quot;方法二：在对话中自然触发&quot;">​</a></h3><p>在对话过程中，Codex 会根据对话内容自动判断是否需要保存记忆。你也可以主动告诉它：</p><ul><li>「请记住：我习惯用 pnpm 而不是 npm」</li><li>「请记住：我的项目用中文注释」</li><li>「请记住：不要自动运行 git commit」</li></ul><p>Codex 会把这些信息保存到 Memory 中，后续新对话会自动加载。</p><h3 id="方法三-通过全局-agents-md-替代" tabindex="-1">方法三：通过全局 AGENTS.md 替代 <a class="header-anchor" href="#方法三-通过全局-agents-md-替代" aria-label="Permalink to &quot;方法三：通过全局 AGENTS.md 替代&quot;">​</a></h3><p>Memory 的另一种实现方式是在全局 AGENTS.md 中写入持久规则：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>C:\\Users\\&lt;你的用户名&gt;\\.codex\\AGENTS.md</span></span></code></pre></div><p>这个文件里的内容会在所有项目的所有对话中生效，效果类似 Memory，但更显式、更可控。</p><hr><h2 id="memory-vs-agents-md-vs-config-toml" tabindex="-1">Memory vs AGENTS.md vs config.toml <a class="header-anchor" href="#memory-vs-agents-md-vs-config-toml" aria-label="Permalink to &quot;Memory vs AGENTS.md vs config.toml&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>Memory</th><th>全局 AGENTS.md</th><th>config.toml</th></tr></thead><tbody><tr><td>存放位置</td><td>.codex/memories/</td><td>.codex/AGENTS.md</td><td>.codex/config.toml</td></tr><tr><td>适合写什么</td><td>个人偏好、沟通习惯、通用规则</td><td>通用指令、语言偏好、行为约束</td><td>模型、沙盒、审批、MCP 等技术配置</td></tr><tr><td>谁管理</td><td>Codex 自动 + 手动 /memories</td><td>你手动编辑</td><td>你手动编辑</td></tr><tr><td>作用范围</td><td>所有对话</td><td>所有对话</td><td>所有对话</td></tr><tr><td>可见性</td><td>隐式，Codex 自动加载</td><td>显式，你直接看到和编辑</td><td>显式，你直接看到和编辑</td></tr></tbody></table><p>推荐组合：</p><ul><li>个人偏好和沟通习惯 → 写进 Memory 或全局 AGENTS.md</li><li>技术配置（模型、沙盒、MCP）→ 写进 config.toml</li><li>项目特定规则 → 写进项目根目录的 AGENTS.md</li></ul><hr><h2 id="memory-的工作原理" tabindex="-1">Memory 的工作原理 <a class="header-anchor" href="#memory-的工作原理" aria-label="Permalink to &quot;Memory 的工作原理&quot;">​</a></h2><ol><li>Codex 在对话过程中，根据你的指令或对话内容判断需要保存什么。</li><li>保存的条目写入 .codex/memories/ 目录。</li><li>下次新开对话时，Codex 会自动读取 memories 目录中的所有条目，作为对话的初始上下文。</li><li>你不需要每次重新告诉 Codex 你的偏好。</li></ol><hr><h2 id="调试命令-进阶" tabindex="-1">调试命令（进阶） <a class="header-anchor" href="#调试命令-进阶" aria-label="Permalink to &quot;调试命令（进阶）&quot;">​</a></h2><p>Codex CLI 中有两个调试用的 Memory 命令：</p><ul><li>/debug-m-drop — 删除 Memory 条目（谨慎使用）</li><li>/debug-m-update — 更新 Memory 条目（谨慎使用）</li></ul><p>这两个命令在正常对话中不建议使用，仅供调试排查。</p><hr><h2 id="实用建议" tabindex="-1">实用建议 <a class="header-anchor" href="#实用建议" aria-label="Permalink to &quot;实用建议&quot;">​</a></h2><ol><li><strong>不要把 Memory 当垃圾桶</strong>：只保存真正重要的、跨对话都需要的偏好和规则。</li><li><strong>敏感信息不要存</strong>：密码、token、API Key 等不要保存到 Memory 中。</li><li><strong>定期检查</strong>：用 /memories 查看当前保存了什么，删除过时或错误的条目。</li><li><strong>配合 AGENTS.md 使用</strong>：如果规则是团队共享的，写进项目 AGENTS.md 而不是个人 Memory。</li><li><strong>沟通偏好最值得存</strong>：比如「用中文回答」「不要自动 git commit」「代码用驼峰命名」等。</li></ol><hr><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Memory 让 Codex 在新对话中也记得你的偏好。</li><li>通过 /memories 命令管理，或在对话中自然触发保存。</li><li>敏感信息不要存，只保存真正重要的通用偏好。</li><li>配合项目 AGENTS.md 和 config.toml 一起使用，效果最好。</li></ul><hr>',45);function c(p,u,y,x,b,g){const t=r("VPNolebaseInlineLinkPreview");return d(),i("div",null,[h,e("blockquote",null,[e("p",null,[o("📎 "),l(t,{href:"/ocdsync/笔记/"},{default:s(()=>[o("📒 返回笔记索引")]),_:1})])])])}const _=a(n,[["render",c]]);export{M as __pageData,_ as default};
